node -e "
const fs = require('fs');
const content = fs.readFileSync('/workspaces/semio/compose/js/sketchpad/shared.ts', 'utf8');
let depth = 0;
const lines = content.split('\n');
// Find all lines where function opens but where would be depth=1 never closed
let starts = []; // stack of line numbers when depth goes from 0 to 1
let line1Open = -1;
for (let i = 0; i < lines.length; i++) {
  const line = lines[i];
  const noComments = line.replace(/\/\/.*/g, '');
  for (const ch of noComments) {
    if (ch === '{') {
      if (depth === 0) line1Open = i+1;
      depth++;
    }
    if (ch === '}') depth--;
  }
}
console.log('Last open at depth 1:', line1Open, 'final depth:', depth);
" 2>&1

