import { Guid, Kit, KitDiff } from "../compose";

// #endregion Imports

// #region Types

// #region YPath Types

// [👤compose📚js🗃️sketchpad💻sharedts🔖types](composerepo://section/COMPOSE/JS/SKETCHPAD/SHARED.TS/TYPES)
// MUST define path segment and path types for navigating Y.js document structures.

/**
 * A single segment in a Y.js document path, either a map key, array index, or array item by ID.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖ypathtypes🛠️ypathsegment](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/YPath%20Types/d/i/YPathSegment)
 **/
export type YPathSegment = { kind: "mapKey"; key: string } | { kind: "arrayIndex"; index: number } | { kind: "arrayItemById"; id: string; idKey: string };

/**
 * An ordered sequence of YPathSegment values describing a path through a Y.js document.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖ypathtypes🛠️ypath](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/YPath%20Types/d/i/YPath)
 **/
export type YPath = YPathSegment[];

// #endregion YPath Types

// #region Granular Hook Types

// [👤compose📚js🗃️sketchpad💻sharedts🔖types🔖granularhooktypes](composerepo://section/COMPOSE/JS/SKETCHPAD/SHARED.TS/TYPES/GRANULAR-HOOK-TYPES)
// MUST define hook result tuples and field abstractions for granular reactive state access.

/**
 * A readonly tuple of value, optional setter, and canSet flag for granular hook access.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🛠️hookresult](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/HookResult)
 **/
export type HookResult<T> = readonly [T, ((value: T) => void) | undefined, boolean];

/**
 * A readonly tuple of value, undefined setter, and canSet flag for read-only hook access.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🛠️hooknosetresult](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/HookNoSetResult)
 **/
export type HookNoSetResult<T> = readonly [T, undefined, boolean];

/**
 * Sentinel undefined value indicating that a hook result has no setter.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🪨readonlysetter](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/READONLY_SETTER)
 **/
export const READONLY_SETTER = undefined as undefined;
/**
 * Sentinel false value indicating that a hook result is read-only.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🪨readonlycan](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/READONLY_CAN)
 **/
export const READONLY_CAN = false;

/**
 * Wraps a value into a read-only HookResult tuple with no setter.
 *
 * MUST return a frozen readonly tuple with undefined setter and false canSet.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🛠️readonlyhookresult](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/readonlyHookResult)
 **/
export function readonlyHookResult<T>(value: T): HookResult<T> {
  return [value, READONLY_SETTER, READONLY_CAN] as const;
}

/**
 * Wraps a value and setter into a writable HookResult tuple.
 *
 * MUST return a tuple with the setter included only when canSet is true.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🛠️writablehookresult](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/writableHookResult)
 **/
export function writableHookResult<T>(value: T, setter: (value: T) => void, canSet: boolean = true): HookResult<T> {
  return [value, canSet ? setter : undefined, canSet] as const;
}

/**
 * Wraps a value into a HookResult tuple with a setter conditional on canSet.
 *
 * MUST return a tuple with the setter conditional on the canSet flag.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🛠️conditionalhookresult](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/conditionalHookResult)
 **/
export function conditionalHookResult<T>(canSet: boolean, value: T, setter: ((value: T) => void) | undefined): HookResult<T> {
  return [value, canSet ? setter : undefined, canSet] as const;
}

/**
 * A reactive field with a value, canSet flag, and setter function.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🛠️field](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/Field)
 **/
export interface Field<T> {
  value: T;
  canSet: boolean;
  set: (next: T) => void;
}

/**
 * A reactive action field with canExecute flag and execute function.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🛠️actionfield](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/ActionField)
 **/
export interface ActionField {
  canExecute: boolean;
  execute: () => void;
}

// [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🪨noopsetter](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/NOOP_SETTER)
/**
 * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🪨noopsetter](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/NOOP_SETTER)
 * NOOP_SETTER holds the data fields for a NOOP_SETTER record.
 **/
const NOOP_SETTER = () => {
  if (process.env.NODE_ENV === "development") {
    console.warn("[DEBUG] Attempted to set a disabled field");
  }
};

/**
 * Constructs a Field with a value, setter, and canSet flag.
 *
 * MUST use the provided setter when canSet is true, otherwise a no-op setter.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🛠️createfield](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/createField)
 **/
export function createField<T>(value: T, setter: (next: T) => void, canSet: boolean): Field<T> {
  return {
    value,
    canSet,
    set: canSet ? setter : NOOP_SETTER,
  };
}

/**
 * Constructs a read-only Field with a fixed value and no-op setter.
 *
 * MUST set canSet to false and use a no-op setter.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🛠️createreadonlyfield](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/createReadonlyField)
 **/
export function createReadonlyField<T>(value: T): Field<T> {
  return {
    value,
    canSet: false,
    set: NOOP_SETTER,
  };
}

/**
 * Constructs an ActionField with a guarded execute function.
 *
 * MUST guard execute behind canExecute, logging a warning in dev mode when disabled.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🛠️createaction](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/createAction)
 **/
export function createAction(execute: () => void, canExecute: boolean): ActionField {
  return {
    canExecute,
    execute: canExecute
      ? execute
      : () => {
        if (process.env.NODE_ENV === "development") {
          console.warn("[DEBUG] Attempted to execute a disabled action");
        }
      },
  };
}

/**
 * Converts a Field to a HookResult tuple.
 *
 * MUST convert the field's canSet and set properties into the hook result format.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🛠️fieldtohookresult](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/fieldToHookResult)
 **/
export function fieldToHookResult<T>(field: Field<T>): HookResult<T> {
  return [field.value, field.canSet ? field.set : undefined, field.canSet] as const;
}

/**
 * Converts a HookResult tuple back to a Field.
 *
 * MUST reconstruct a Field from the tuple, using a no-op setter when undefined.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🛠️hookresulttofield](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/d/i/hookResultToField)
 **/
export function hookResultToField<T>(result: HookResult<T>): Field<T> {
  const [value, setter, canSet] = result;
  return {
    value,
    canSet,
    set: setter ?? NOOP_SETTER,
  };
}

// #endregion Granular Hook Types

// #region Standard Empty Constants

// [👤compose📚js🗃️sketchpad💻sharedts🔖types🔖standardemptyconstants](composerepo://section/COMPOSE/JS/SKETCHPAD/SHARED.TS/TYPES/STANDARD-EMPTY-CONSTANTS)
// MUST provide frozen singleton constants for empty collections and default panel visibility.

/**
 * Frozen empty array singleton for default array values.
 *
 *  * [👤compose📚js🗃️sketchpad💻shared🔖types🔖granularhooktypes🔖standardemptyconstants🪨emptyarray](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/shared.ts/s/Types/s/Granular%20Hook%20Types/s/Standard%20Empty%20Constants/d/i/EMPTY_ARRAY)
