          : hasControls && <div className="absolute top-1 right-1 z-panel flex items-stretch gap-single">{controlsContent}</div>}
        {error ? <DefaultErrorDisplay error={error} /> : loading && skeleton ? skeleton : children}
      </div>
    </LevelProvider>
  );
