      });
    }
    return (
      <span data-slot="breadcrumb-link" className="cursor-selectable">
        {itemContent}
      </span>
    );
  }, [itemContent]);

  const itemElement = (
    <li data-slot="breadcrumb-item" id={id} className={cn("flex items-stretch cursor-selectable", className)} {...props}>
      {interactiveContent}
    </li>
  );

  if (id) {
