  private recompute() {
    const next = this.compute();
    const nextJson = JSON.stringify(next, DerivedNode.jsonReplacer);
    if (nextJson !== this.valueJson) {
      this.value = next;
      this.valueJson = nextJson;
      this.version++;
      this.subscribers.forEach((cb) => cb());
    }
