        this.initialized = false;
        this.value = undefined;
        this.valueJson = undefined;
        this.version = 0;
      }
    };
  }

  dispose() {
    this.unsubscribers.forEach((u) => u());
    this.unsubscribers = [];
    this.subscribers.clear();
    this.initialized = false;
    this.value = undefined;
    this.valueJson = undefined;
    this.version = 0;
