    if (local) {
      this.persistence = new IndexeddbPersistence(`compose-kit-${kit.guid}`, this.yDoc);
    }

    if (remote && this.remoteProviders) {
      this.remoteProviders.yProvider(this.yDoc, this.name + "@" + this.version);
