 *
 *  * [👤compose📚js🗃️sketchpad💻sketchpad🔖commands🪨kitcommands](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Commands/d/i/kitCommands)
 **/
export const kitCommands = {
  "compose.kit.createAuthor": (context: KitCommandContext, author: Author): KitCommandResult => {
    return {
      diff: { authors: { added: [author] } },
    };
  },
  "compose.kit.updateAuthor": (context: KitCommandContext, guid: Guid, diff: AuthorDiff): KitCommandResult => {
    return {
      diff: { authors: { updated: [{ author: { guid }, diff }] } },
    };
  },
