/**
 * Hook returning whether the given event can be sent to the sketchpad actor.
 *
 *  * [👤compose📚js🗃️sketchpad💻sketchpad🔖apps🔖sketchpad🔖xstatehooks🛠️usesketchpadcan](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps/s/Sketchpad/s/XState%20Hooks/d/i/useSketchpadCan)
 **/
export function useSketchpadCan(event: SketchpadEvent): boolean {
  const actor = useSketchpadActor();
  return useSelector(actor, (snapshot) => {
    const handler = getEventHandler(event.type);
    if (!handler) return false;
    if (handler.guard && !handler.guard(snapshot.context as any, event as any)) return false;
    return true;
  });
}

