 **/
export function usePieceCenterU(): HookResult<number> {
  const pieceScope = usePieceScope();
  const piece = usePiece() as Piece | null;
  const { useDesignAppCommands } = getDesignAppHooks();
  const commands = useDesignAppCommands();
  const setter = useCallback(
    (value: number) => {
      if (pieceScope && piece) commands.updatePiece("compose.sketchpad.app.design.panel.details.section.piece.center.u", pieceScope.guid, { center: { u: value, v: piece.center?.v ?? 0 } });
