                      {activeToolbarGroup && toolbarGroups[activeToolbarGroup] && (
                        <div id="compose.sketchpad.toolbar.zone.settings" className="absolute left-[4px] top-0 h-full max-w-[calc(50vw-1rem)] pointer-events-auto">
