      return this.cache;
    }

    const model: Model = {
      guid: this.guid,
      file: this.file,
      description: this.description,
      tags,
    };

    this.cache = model;
    this.cacheHash = currentHash;
    return model;
  }

  apply(diff: ModelDiff): void {
    if (diff.file !== undefined) this.file = diff.file;
    if (diff.description !== undefined) this.description = diff.description;
