  if (diff.language !== undefined) next = { ...next, language: diff.language };
  if (diff.device) next = { ...next, device: diff.device };
  if (diff.expertise) next = { ...next, expertise: diff.expertise };
  if (diff.mode) next = { ...next, mode: diff.mode };
