  },
  actions: {
    navigate: () => {},
    navigateImpl: assign(({ context, event }) => {
      if (event.type !== "NAVIGATE") return {};
      const currentNav = context.sketchpad.navigation;
      const index = context.sketchpad.navigationHistoryIndex ?? 0;
      if (currentNav === event.path) {
