        }
      }
      if (diff.folders) {
        if (diff.folders.added) {
          diff.folders.added.forEach((folder) => this.createFolder(folder));
        }
        if (diff.folders.updated) {
          diff.folders.updated.forEach(({ folder, diff: folderDiff }) => {
