  const kitScope = useKitScope();
  const resolvedGuid = guid ?? kitScope?.guid;
  const kitStore = useKitStore(identitySelector, resolvedGuid) as KitStore | null;

  const subscribe = useCallback(
    (callback: () => void) => {
      if (!kitStore) return () => {};
