/** AppRegistry holds the data fields for a AppRegistry record.
// [👤compose📚js🗃️sketchpad💻sketchpad🔖appsregistry🛠️appregistry](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Apps%20Registry/d/i/AppRegistry)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖appsregistry🛠️appregistry](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Apps%20Registry/d/i/AppRegistry)
 **/
class AppRegistry {
  private apps: Map<string, AppRegistration> = new Map();
  private autoDiscovered = false;
  private _initialized = false;
  private listeners = new Set<() => void>();

  get isInitialized(): boolean {
    return this._initialized || this.apps.size > 0;
  }

  subscribe(listener: () => void): () => void {
    this.listeners.add(listener);
    return () => {
      this.listeners.delete(listener);
    };
  }

  private notify() {
    this.listeners.forEach((listener) => listener());
  }

  private async autoDiscover(): Promise<void> {
    if (this.autoDiscovered) return;
    this.autoDiscovered = true;

    const appModules = import.meta.glob<{ config: AppConfig }>("./apps/*/App.tsx");

    for (const [path, importFn] of Object.entries(appModules)) {
      const module = await importFn();
      if (module.config) {
        this.register(module.config);
      }
    }
  }

  register(registration: AppRegistration): void {
    if (this.apps.has(registration.id)) return;
    this.apps.set(registration.id, registration);
    this.cachedApps = null;
    this.notify();
  }

  unregister(id: string): void {
    this.apps.delete(id);
    this.cachedApps = null;
    this.notify();
  }

  getApp(id: string): AppRegistration | undefined {
    return this.apps.get(id);
  }

  private cachedApps: AppRegistration[] | null = null;

  getAllApps(): AppRegistration[] {
    if (!this.cachedApps) {
      this.cachedApps = Array.from(this.apps.values()).sort((a, b) => (a.order || 0) - (b.order || 0));
    }
    return this.cachedApps;
  }

  getAppForPath(pathParts: string[]): AppRegistration | undefined {
    const matches = this.getAllApps().filter((app) => app.matchesPath && app.matchesPath(pathParts));
    if (matches.length === 0) return undefined;
    return matches.sort((a, b) => {
      const aSegmentCount = a.routeSegments?.length || 0;
      const bSegmentCount = b.routeSegments?.length || 0;
      if (aSegmentCount !== bSegmentCount) {
        return bSegmentCount - aSegmentCount;
      }
      return (a.order || 0) - (b.order || 0);
