    }
  }

  hash = (group: Group): string => {
    return JSON.stringify(group);
  };

  snapshot = (): Group => {
    const currentData = {
      guid: this.guid,
      pieces: this.pieces.map((guid) => ({ guid })),
      color: this.color,
      name: this.name,
      description: this.description,
    };
    const currentHash = this.hash(currentData);
    if (!this.cache || this.cacheHash !== currentHash) {
