  appConfigsLoadPromise = (async () => {
    const modules = await Promise.all([
      import("./Home"),
      import("./Kit"),
      import("./Type"),
      import("./Quality"),
      import("./Design"),
      import("./Docs"),
      import("./Feedback"),
