 **/
type YAttribute = Y.Map<YAttributeVal>;

/**
// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖kits🛠️attributestore](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/Kits/d/i/AttributeStore)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖coord🛠️ycoordval](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/Coord/d/i/YCoordVal)
 *
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖plainappstorenoyjs🔖kits🛠️attributestore](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Plain%20App%20Store%20(No%20YJS)/s/Kits/d/i/AttributeStore)
 **/
class AttributeStore {
  private yAttribute: YAttribute;
  private cache?: Attribute;
  private cacheHash?: string;

  constructor(yAttribute: YAttribute, attribute: Attribute) {
    this.yAttribute = yAttribute;
  }

  get key(): string {
    return this.yAttribute.get("key") as string;
  }
  set key(key: string) {
    this.yAttribute.set("key", key);
  }

  get value(): string | undefined {
    return this.yAttribute.get("value") as string | undefined;
  }
  set value(value: string | undefined) {
    this.yAttribute.set("value", value || "");
  }

  get definition(): string | undefined {
    return this.yAttribute.get("definition") as string | undefined;
  }
  set definition(definition: string | undefined) {
    this.yAttribute.set("definition", definition || "");
  }

  get guid(): string {
    return this.yAttribute.get("guid") as string;
  }
  set guid(guid: string) {
    this.yAttribute.set("guid", guid);
  }

  hash = (attribute: Attribute): string => {
    return JSON.stringify(attribute);
  };

  snapshot = (): Attribute => {
    const currentData = {
      guid: this.guid,
      key: this.key,
      value: this.value,
      definition: this.definition,
    };
    const currentHash = this.hash(currentData);
    if (!this.cache || this.cacheHash !== currentHash) {
      this.cacheHash = currentHash;
      this.cache = currentData;
    }
    return this.cache;
