 **/
export function useCurrentPiecePlane(): Plane {

  if (!plane) {
    return {
      origin: { x: 0, y: 0, z: 0 },
      xAxis: { x: 1, y: 0, z: 0 },
      yAxis: { x: 0, y: 1, z: 0 },
    };
  }

  return plane;
}

