        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      } catch (error) {
        throw error;
      }
    })();
    return { diff: {} };
  },
  "compose.kit.addPiece": (context: KitCommandContext, guid: Guid, piece: Piece): KitCommandResult => {
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: {
                pieces: {
                  added: [
                    piece.plane || (findDesignInKit(context.kit, guid)?.connections ?? []).some((connection) => connection.connected.piece.guid === piece.guid || connection.connecting.piece.guid === piece.guid)
                      ? piece
                      : {
                          ...piece,
                          plane: {
                            origin: { x: 0, y: 0, z: 0 },
                            xAxis: { x: 1, y: 0, z: 0 },
                            yAxis: { x: 0, y: 1, z: 0 },
                          },
                        },
                  ],
                },
              },
            },
          ],
        },
      },
    };
  },
  "compose.kit.addPieces": (context: KitCommandContext, guid: Guid, pieces: Piece[]): KitCommandResult => {
    const design = findDesignInKit(context.kit, guid);
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: {
                pieces: {
                  added: pieces.map((candidate) =>
                    candidate.plane || (design?.connections ?? []).some((connection) => connection.connected.piece.guid === candidate.guid || connection.connecting.piece.guid === candidate.guid)
                      ? candidate
                      : {
                          ...candidate,
                          plane: {
                            origin: { x: 0, y: 0, z: 0 },
                            xAxis: { x: 1, y: 0, z: 0 },
                            yAxis: { x: 0, y: 1, z: 0 },
                          },
                        },
                  ),
                },
              },
            },
          ],
        },
      },
    };
  },
  "compose.kit.removePiece": (context: KitCommandContext, guid: Guid, piece: Guid): KitCommandResult => {
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: { pieces: { removed: [{ guid: piece }] } },
            },
          ],
        },
      },
    };
  },
  "compose.kit.removePieces": (context: KitCommandContext, guid: Guid, pieces: Guid[]): KitCommandResult => {
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: { pieces: { removed: pieces.map((p) => ({ guid: p })) } },
            },
          ],
        },
      },
    };
  },
  "compose.kit.addConnection": (context: KitCommandContext, guid: Guid, connection: Connection): KitCommandResult => {
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: { connections: { added: [connection] } },
            },
          ],
        },
      },
    };
  },
  "compose.kit.addConnections": (context: KitCommandContext, guid: Guid, connections: Connection[]): KitCommandResult => {
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: { connections: { added: connections } },
            },
          ],
        },
      },
    };
  },
  "compose.kit.removeConnection": (context: KitCommandContext, guid: Guid, connectionGuid: Guid): KitCommandResult => {
    const design = findDesignInKit(context.kit, guid);
    const connection = design?.connections?.find((c) => c.guid === connectionGuid);
    if (!connection) return { diff: {} };
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: { connections: { removed: [{ guid: connection.guid }] } },
            },
          ],
        },
      },
    };
  },
  "compose.kit.removeConnections": (context: KitCommandContext, guid: Guid, connectionGuids: Guid[]): KitCommandResult => {
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: { connections: { removed: connectionGuids.map((connGuid) => ({ guid: connGuid })) } },
            },
          ],
        },
      },
    };
  },
};

