  private loadKitFilesFromPublic = async (kitGuid: string, kitStore: KitStore) => {
    try {
      const zipUrl = `/public/${kitGuid}.zip`;
      const response = await fetch(zipUrl);

      if (!response.ok) {
        return;
      }

      const blob = await response.blob();

      const JSZip = (await import("jszip")).default;
      const zip = await JSZip.loadAsync(blob);

      const filePromises: Promise<void>[] = [];
      zip.forEach((relativePath, zipEntry) => {
        if (!zipEntry.dir) {
          filePromises.push(
            zipEntry.async("blob").then(async (fileBlob) => {
              const file: ComposeFile = {
                guid: guid(),
                name: relativePath.split("/").pop() || relativePath,
                size: fileBlob.size,
                hash: undefined,
                createdAt: new Date().toISOString(),
                updatedAt: new Date().toISOString(),
              };
              await kitStore.execute("compose.kit.addFile", "system.loadKitFiles", file, fileBlob);
            }),
          );
        }
      });

      await Promise.all(filePromises);
    } catch (error) {}
  };

