/**
 * Hook returning all types in the targeted kit.
 *
 *  * [👤compose📚js🗃️sketchpad💻sketchpad🔖kit🔖targetedkithooks🛠️usekittypes](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Kit/s/Targeted%20Kit%20Hooks/d/i/useKitTypes)
 **/
export function useKitTypes(guid?: Guid): Type[] {
  const kitScope = useKitScope();
  const resolvedGuid = guid ?? kitScope?.guid;
  const kitStore = useKitStore(identitySelector, resolvedGuid) as KitStore | null;

  const subscribe = useCallback(
    (callback: () => void) => {
      if (!kitStore) return () => {};
      return kitStore.onTypesChanged((cb: () => void) => {
        cb();
        callback();
        return () => {};
      }, true);
    },
    [kitStore],
  );

  const getSnapshot = useCallback(() => {
    if (!kitStore) return EMPTY_TYPES;
    return kitStore.snapshotTypes();
  }, [kitStore]);

  return useSyncExternalStore(subscribe, getSnapshot);
}

