      if (!kitStore) return () => {};
      return kitStore.onFoldersChanged((cb: () => void) => {
        cb();
        callback();
        return () => {};
      }, true);
    },
    [kitStore],
  );

  const getSnapshot = useCallback(() => {
    if (!kitStore) return EMPTY_FOLDERS;
    return kitStore.snapshotFolders();
  }, [kitStore]);

  return useSyncExternalStore(subscribe, getSnapshot);
}

