  );

  const handleCreate = useCallback(
    (origin: string) => {
      if (!kit || !filteredKind || !kitCommands) return;

      switch (filteredKind) {
        case "designs":
          handleCreateDesign(origin);
          break;
        case "types":
          handleCreateType(origin);
          break;
        case "authors":
          const guid = crypto.randomUUID();
