    });

    Object.keys(groups).forEach(key => {
      groups[key].sort((a, b) => (a.toolbarGroup?.order ?? 0) - (b.toolbarGroup?.order ?? 0));
    });
    return groups;
  }, [toolbarSections]);

  useEffect(() => {
    const groupOrder = ["hand", "selection", "filter", "create", "view", "actions"];
    const firstGroup = groupOrder.find((g) => g !== "hand" && toolbarGroups[g]);
    setActiveToolbarGroup((prev) => (prev === null || (prev !== null && !toolbarGroups[prev]) ? firstGroup ?? null : prev));
  }, [toolbarGroups]);

  const toggleToolbarGroup = useCallback((id: string) => {
    setActiveToolbarGroup(prev => {
      return prev === id ? null : id;
    });
  }, []);

  const [activeSubToolByGroup, setActiveSubToolByGroup] = useState<Record<string, string>>({});

  const setSubTool = useCallback((groupId: string, subToolId: string) => {
    setActiveSubToolByGroup((prev) => ({ ...prev, [groupId]: subToolId }));
    setActiveToolbarGroup(groupId);
  }, []);

  const getGroupIcon = useCallback((groupId: string) => {
    switch (groupId) {
      case "hand":
        return <HandIcon className="size-tiny" />;
      case "selection":
        return <MousePointerIcon className="size-tiny" />;
      case "filter":
        return <SearchIcon className="size-tiny" />;
      case "create":
        return <AddIcon className="size-tiny" />;
      case "view":
        return <LayoutIcon className="size-tiny" />;
      case "actions":
        return <MoreHorizontalIcon className="size-tiny" />;
      default:
        return <FocusIcon className="size-tiny" />;
    }
  }, []);

  const sensors = useSensors(
    useSensor(PointerSensor, {
      activationConstraint: {
        distance: 8, // 8px of movement required before drag starts
      },
    }),
  );

  const customCollisionDetection = useCallback((args: any) => {
    const pointerCollisions = pointerWithin(args);

    if (pointerCollisions.length > 0) {
      return pointerCollisions;
    }

    const rectCollisions = rectIntersection(args);

    if (rectCollisions.length > 0) {
      return rectCollisions;
    }

    const centerCollisions = closestCenter(args);

    if (centerCollisions && centerCollisions.length > 0) {
      return centerCollisions;
    }
    return [];
  }, []);
  const kitShallows = useKitShallows();
  const getTypeOrDesignName = useCallback(() => {
    if (!activeDragData) return null;
    if (activeDragData.type === "type") {
      const kitId = activeDragData.typeGuid?.split("-")[0];
      const kit = kitShallows.find((k) => k.guid.startsWith(kitId));
      const type = kit?.types?.find((t: any) => typeof t === "object" && t.guid === activeDragData.typeGuid) as any;
      return type?.name || "Type";
    } else if (activeDragData.type === "design") {
      const kitId = activeDragData.designGuid?.split("-")[0];
      const kit = kitShallows.find((k) => k.guid.startsWith(kitId));
      const design = kit?.designs?.find((d: any) => typeof d === "object" && d.guid === activeDragData.designGuid) as any;
      return design?.name || "Design";
    }
    return null;
  }, [activeDragData, kitShallows]);
  return (
    <TutorialProvider store={tutorialStore}>
      <GlobalFooterItems />
      <DndContext
        sensors={sensors}
        collisionDetection={customCollisionDetection}
        onDragStart={(event) => {
          setActiveDragId(event.active.id as string);
          setActiveDragData(event.active.data.current);

          sketchpadCommands.setActiveInteraction("compose.sketchpad.drag", "dragging");
        }}
        onDragEnd={(event) => {
          setActiveDragId(null);
          setActiveDragData(null);

          sketchpadCommands.setActiveInteraction("compose.sketchpad.drag", undefined);

          const customEvent = new CustomEvent("design-drag-end", { detail: event });
          window.dispatchEvent(customEvent);
        }}
      >
        <LevelProvider level="base">
          <ToolbarScopeWrapper>
            <LayoutComponent
              className="bg-base text-foreground relative border"
              navbar={<Navbar items={navbarItems} />}
              footer={
                <Footer
                  items={footerItems.map((item) => ({
                    id: item.id,
                    icon: item.icon,
                    text: item.text,
                    content: item.content,
                    order: item.order,
                    onClick: item.onClick,
                  }))}
                  isVisible={isFooterExpanded || !isFullscreen}
                />
              }
              bottomPanel={
                consoleSections.length > 0
                  ? {
                      visible: true,
                      size: panelSizes.consoleHeight,
                      onSizeChange: (size: number) => sketchpadCommands.setPanelSize("compose.sketchpad", "consoleHeight", size),
                      sections: consoleSections,
                      panelKey: "console",
                    }
                  : undefined
              }
              leftSidePanel={
                leftSidePanelTabs.length > 0 && panelVisibility.leftSidePanel
                  ? {
                      position: "left" as const,
                      visible: true,
                      size: panelSizes.leftSidePanelWidth,
                      onSizeChange: (size: number) => sketchpadCommands.setPanelSize("compose.sketchpad", "leftSidePanelWidth", size),
                      tabs: leftSidePanelTabs,
                      activeTabId: activeLeftTabId,
                      onActiveTabChange: setActiveLeftTabId,
                    }
                  : undefined
              }
              rightSidePanel={
                panelVisibility.chat
                  ? {
                      position: "right" as const,
                      visible: true,
                      size: panelSizes.chatWidth,
                      onSizeChange: (size: number) => sketchpadCommands.setPanelSize("compose.sketchpad", "chatWidth", size),
                      tabs: [
                        {
                          id: "chat",
                          icon: ChatIcon,
                          order: 0,
                          content: () => {
                            const chatTab = rightSidePanelTabs.find(t => t.id.includes("chat"));
                            return chatTab ? (typeof chatTab.content === "function" ? chatTab.content() : chatTab.content) : (
                              <BasicChatPanel id={`compose.sketchpad.app.${appType}.chat`} title={appType.charAt(0).toUpperCase() + appType.slice(1)} />
                            );
                          },
                        },
                      ],
                      activeTabId: "chat",
                      onActiveTabChange: () => {},
                      minSize: 150,
                      maxSize: 500,
                      className: rightSidePanelElementSizingClassName,
                    }
                  : panelVisibility.settings
                    ? {
                        position: "right" as const,
                        visible: true,
                        size: panelSizes.settingsWidth,
                        onSizeChange: (size: number) => sketchpadCommands.setPanelSize("compose.sketchpad", "settingsWidth", size),
                        tabs: [
                          {
                            id: "settings",
                            icon: SettingsIcon,
                            order: 0,
                            content: () => {
                              const settingsTab = rightSidePanelTabs.find(t => t.id.includes("settings"));
                              return settingsTab ? (typeof settingsTab.content === "function" ? settingsTab.content() : settingsTab.content) : (
                                <UtilityFallbackSettingsContent appType={appType} />
                              );
                            },
                          },
                        ],
                        activeTabId: "settings",
                        onActiveTabChange: () => {},
                        minSize: 150,
                        maxSize: 500,
                        className: rightSidePanelElementSizingClassName,
                      }
                    : rightSidePanelTabs.filter((t) => !t.id.endsWith(".chat") && !t.id.endsWith(".settings")).length > 0 && panelVisibility.rightSidePanel
                      ? {
                          position: "right" as const,
                          visible: true,
                          size: panelSizes.rightSidePanelWidth,
                          onSizeChange: (size: number) => sketchpadCommands.setPanelSize("compose.sketchpad", "rightSidePanelWidth", size),
                          tabs: rightSidePanelTabs.filter((t) => !t.id.endsWith(".chat") && !t.id.endsWith(".settings")),
                          activeTabId: activeRightTabId,
                          onActiveTabChange: setActiveRightTabId,
                          minSize: 150,
                          maxSize: 500,
                          className: rightSidePanelElementSizingClassName,
                        }
                      : undefined
              }
              toolbar={
                panelVisibility.toolbar || appType === "type" || appType === "design" || appType === "feedback" || appType === "kit" || appType === "home" || appType === "quality" || appType === "docs" ? (
                  toolbarSections.length > 0 ? (
                    <div role="toolbar" id="compose.sketchpad.toolbar" className="absolute bottom-1.5 left-0 right-0 h-[40px] pointer-events-none px-2">
                    <div id="compose.sketchpad.toolbar.seam" className="absolute left-1/2 top-0 h-full w-0 -translate-x-1/2">
                      <div id="compose.sketchpad.toolbar.zone.tools" className="absolute right-[4px] top-0 h-full max-w-[calc(50vw-1rem)] pointer-events-auto">
                        <LevelProvider level="panel">
                          <ToolbarZone>
                            {["hand", "selection", "filter", "create", "view", "actions"].map((groupId) => {
                              if (!toolbarGroups[groupId]) return null;
                              const isActive = activeToolbarGroup === groupId;

                              if (groupId === "selection") {
                                const activeSubToolId = activeSubToolByGroup[groupId] || toolbarGroups[groupId].find((s) => s.toolbarGroup?.subToolId)?.toolbarGroup?.subToolId;
                                const uniqueSubTools = Array.from(new Set(toolbarGroups[groupId].map((s) => s.toolbarGroup?.subToolId).filter(Boolean))) as string[];
                                if (uniqueSubTools.length === 0) {
                                  return (
                                    <Toggle
                                      key={groupId}
                                      kind="single"
                                      id={`compose.sketchpad.toolbar.group.${groupId}`}
                                      pressed={isActive}
                                      onPressedChange={() => toggleToolbarGroup(groupId)}
                                      icon={getGroupIcon(groupId)}
                                      text={i18n.t(`compose.sketchpad.toolbar.parent.${groupId}`)}
                                    />
                                  );
                                }

                                return (
                                  <Toggle
                                    key={groupId}
                                    kind="dropdown"
                                    id={`compose.sketchpad.toolbar.group.${groupId}`}
                                    value={activeSubToolId}
                                    pressed={isActive}
                                    onPressedChange={(pressed) => {
                                      setActiveToolbarGroup(pressed ? groupId : null);
                                    }}
                                    onValueChange={(val) => val && setSubTool(groupId, val)}
                                    dropdownSide="top"
                                    dropdownAlign="end"
                                    dropdownSideOffset={2}
                                    dropdownAvoidCollisions={false}
                                    dropdownInstant={true}
                                    dropdownContentClassName="w-[10.5rem] min-w-[10.5rem] p-0 overflow-hidden border transition-none"
                                    items={uniqueSubTools.map((subToolId) => {
                                      const section = toolbarGroups[groupId].find((s) => s.toolbarGroup?.subToolId === subToolId);
                                      return {
                                        value: subToolId,
                                        label: section?.toolbarGroup?.subToolIcon || <FocusIcon className="size-tiny" />,
                                        text: section?.toolbarGroup?.subToolLabelId ? i18n.t(section.toolbarGroup.subToolLabelId) : subToolId,
                                        id: `compose.sketchpad.toolbar.subtool.${subToolId}`,
                                      };
                                    })}
                                  />
                                );
                              }

                              return (
                                <Toggle
                                  key={groupId}
                                  kind="single"
                                  id={`compose.sketchpad.toolbar.group.${groupId}`}
                                  pressed={isActive}
                                  onPressedChange={() => toggleToolbarGroup(groupId)}
                                  icon={getGroupIcon(groupId)}
                                  text={i18n.t(`compose.sketchpad.toolbar.parent.${groupId}`)}
                                />
                              );
                            })}
                          </ToolbarZone>
                        </LevelProvider>
                      </div>

                      {activeToolbarGroup && toolbarGroups[activeToolbarGroup] && (
                        <div id="compose.sketchpad.toolbar.zone.settings" className="absolute left-[4px] top-0 h-full max-w-[calc(50vw-1rem)] pointer-events-auto">
                          <LevelProvider level="panel">
                            <ToolbarZone className="flex-nowrap min-w-0">
                              <ToolbarScopeWrapper>
                                {toolbarGroups[activeToolbarGroup]?.map((section) => {
                                  if (activeToolbarGroup === "selection") {
                                    const activeSubToolId = activeSubToolByGroup["selection"] || toolbarGroups["selection"].find((s) => s.toolbarGroup?.subToolId)?.toolbarGroup?.subToolId;
                                    const hasSelectionSubTools = toolbarGroups["selection"]?.some((s) => Boolean(s.toolbarGroup?.subToolId));
                                    if (hasSelectionSubTools && section.toolbarGroup?.subToolId !== activeSubToolId) return null;
                                  }
                                  return (
                                    <ToolbarItem key={section.id}>
                                      {typeof section.content === "function" ? section.content() : section.content}
                                    </ToolbarItem>
                                  );
                                })}
                              </ToolbarScopeWrapper>
                            </ToolbarZone>
                          </LevelProvider>
                        </div>
                      )}
                    </div>
                  </div>
                  ) : (
                    <div id="compose.sketchpad.toolbar" className="hidden" />
                  )
                ) : undefined
              }
              canvas={
                <div className="relative h-full w-full">
                  <AppRouter />
                </div>
              }
            />
          </ToolbarScopeWrapper>
        </LevelProvider>
        <DragOverlay>
          {activeDragId && activeDragData ? (
            <div className="cursor-grabbing">
              <div className="border border-element rounded-full w-small h-small flex items-center justify-center shadow-lg">
                <span className="text-small font-medium select-none">{getTypeOrDesignName()?.substring(0, 2).toUpperCase() || "?"}</span>
              </div>
            </div>
          ) : null}
        </DragOverlay>
      </DndContext>
    </TutorialProvider>
  );
};

