      if (!currentStack) {
        currentStack = new Y.Array<any>();
        this.yMap.set("currentTransactionStack", currentStack);
      }
      const lastDeletedEdit = (this as any).lastDeletedTransactionEdit;
      if (lastDeletedEdit) {
        currentStack.push([lastDeletedEdit]);
