/**
 * Hook returning the transaction interface for the current kit.
 *
 *  * [👤compose📚js🗃️sketchpad💻sketchpad🔖kit🛠️usekittransaction](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Kit/d/i/useKitTransaction)
 **/
export function useKitTransaction(): Transaction {
  const store = useSketchpadStore();
  const kitScope = useKitScope();
  const kitGuid = kitScope?.guid;
  const getOrigin = useOrigin();

  if (!kitGuid || !store.hasKit(kitGuid)) {
    return {};
  }

  const kitStore = store.kit(kitGuid);
  return {
    start: () => {
      kitStore.yDoc.transact(() => {}, getOrigin());
