 *  * [👤compose📚js🗃️sketchpad💻sketchpad🔖commands🛠️sqlwasmurl](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Commands/d/i/sqlWasmUrl)
 **/
export function useKitCommands() {
  const store = useSketchpadStore();
  const kitScope = useKitScope();
  const kitGuid = kitScope?.guid;
  const getOrigin = useOrigin();

  if (!kitGuid || !store.hasKit(kitGuid)) {
    return null;
  }

  const kitStore = store.kit(kitGuid);
  return {
    importKit: (url: string) => kitStore.execute("compose.kit.import", getOrigin(), url),
    exportKit: () => kitStore.execute("compose.kit.export", getOrigin()),
    createAuthor: (author: Author) => kitStore.execute("compose.kit.createAuthor", getOrigin(), author),
