    addPiece: (design: Guid, piece: Piece) => kitStore.execute("compose.kit.addPiece", getOrigin(), design, piece),
    addPieces: (design: Guid, pieces: Piece[]) => kitStore.execute("compose.kit.addPieces", getOrigin(), design, pieces),
