 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖machine🔖helpers🛠️migratepath](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Machine/s/Helpers/d/i/migratePath)
 **/
function migratePath(path: string): string {
  if (path.match(/^\/kit\/([^/]+)\/design\/([^/]+)/)) {
    return path.replace(/^\/kit\/([^/]+)\/design\/([^/]+)/, "/kits/$1/designs/$2");
  }
  if (path.match(/^\/kit\/([^/]+)\/type\/([^/]+)/)) {
    return path.replace(/^\/kit\/([^/]+)\/type\/([^/]+)/, "/kits/$1/types/$2");
  }
  if (path.match(/^\/kit\/([^/]+)/)) {
    return path.replace(/^\/kit\/([^/]+)/, "/kits/$1");
  }
  if (path.match(/^\/kit\?/)) {
    return path.replace(/^\/kit\?/, "/kits?");
  }
  return path;
}

/** buildSnapshot holds the data fields for a buildSnapshot record.
// [👤compose📚js🗃️sketchpad💻sketchpad🔖machine🔖helpers🛠️applydiff](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Machine/s/Helpers/d/i/applyDiff)
