/** getAppTransaction holds the data fields for a getAppTransaction record.
// [👤compose📚js🗃️sketchpad💻sketchpad🔖machine🔖sketchpadmachine🔖sketchpadselectors🪨getapptransaction](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Machine/s/Sketchpad%20Machine/s/Sketchpad%20Selectors/d/i/getAppTransaction)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖machine🔖sketchpadmachine🔖sketchpadselectors🪨getapptransaction](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Machine/s/Sketchpad%20Machine/s/Sketchpad%20Selectors/d/i/getAppTransaction)
 **/
const getAppTransaction = (context: SketchpadContext, appKey: string): AppTransactionState | undefined => {
  const parts = appKey.split("-");
  if (parts[0] === "design" && parts.length >= 3) {
    const key = `${parts[1]}:${parts.slice(2).join("-")}`;
    return context.designApps[key]?.transaction;
  }
  if (parts[0] === "type" && parts.length >= 3) {
    const key = `${parts[1]}:${parts.slice(2).join("-")}`;
    return context.typeApps[key]?.transaction;
  }
  if (parts[0] === "kit" && parts.length >= 2) {
    return context.kitApps[parts[1]]?.transaction;
  }
  return undefined;
};

/** defaultTransactionState holds the data fields for a defaultTransactionState record.
// [👤compose📚js🗃️sketchpad💻sketchpad🔖machine🔖sketchpadmachine🔖sketchpadselectors🪨defaulttransactionstate](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Machine/s/Sketchpad%20Machine/s/Sketchpad%20Selectors/d/i/defaultTransactionState)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖machine🔖sketchpadmachine🔖sketchpadselectors🪨defaulttransactionstate](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Machine/s/Sketchpad%20Machine/s/Sketchpad%20Selectors/d/i/defaultTransactionState)
 **/
const defaultTransactionState: AppTransactionState = {
  isTransactionActive: false,
  currentTransactionStack: [],
  pastTransactionStack: [],
  redoStack: [],
};

/**
 * Creates a selector for the transaction state of a given app key.
 *
 *  * [👤compose📚js🗃️sketchpad💻sketchpad🔖machine🔖sketchpadmachine🔖sketchpadselectors🪨createtransactionselector](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Machine/s/Sketchpad%20Machine/s/Sketchpad%20Selectors/d/i/createTransactionSelector)
 **/
export const createTransactionSelector = (appKey: string) => (state: { context: SketchpadContext }) => getAppTransaction(state.context, appKey) || defaultTransactionState;

/**
 * Creates a selector returning whether a transaction is active.
 *
 *  * [👤compose📚js🗃️sketchpad💻sketchpad🔖machine🔖sketchpadmachine🔖sketchpadselectors🪨createtransactionisactiveselector](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Machine/s/Sketchpad%20Machine/s/Sketchpad%20Selectors/d/i/createTransactionIsActiveSelector)
 **/
export const createTransactionIsActiveSelector = (appKey: string) => (state: { context: SketchpadContext }) => getAppTransaction(state.context, appKey)?.isTransactionActive ?? false;

/**
 * Creates a selector returning whether an undo operation is available.
 *
 *  * [👤compose📚js🗃️sketchpad💻sketchpad🔖machine🔖sketchpadmachine🔖sketchpadselectors🪨createtransactioncanundoselector](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Machine/s/Sketchpad%20Machine/s/Sketchpad%20Selectors/d/i/createTransactionCanUndoSelector)
 **/
export const createTransactionCanUndoSelector = (appKey: string) => (state: { context: SketchpadContext }) => {
  const tx = getAppTransaction(state.context, appKey);
  if (!tx) return false;
  return tx.isTransactionActive ? tx.currentTransactionStack.length > 0 : tx.pastTransactionStack.length > 0;
};

/**
 * Creates a selector returning whether a redo operation is available.
 *
 *  * [👤compose📚js🗃️sketchpad💻sketchpad🔖machine🔖sketchpadmachine🔖sketchpadselectors🪨createtransactioncanredoselector](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Machine/s/Sketchpad%20Machine/s/Sketchpad%20Selectors/d/i/createTransactionCanRedoSelector)
 **/
export const createTransactionCanRedoSelector = (appKey: string) => (state: { context: SketchpadContext }) => {
  const tx = getAppTransaction(state.context, appKey);
  if (!tx) return false;
  return !tx.isTransactionActive && tx.redoStack.length > 0;
};

