const Focus: FC = ({}) => {
  const [open, setOpen] = useState(false);
  const [query, setQuery] = useState("");
  const focusContext = useFocusSafe();
  const appType = useAppType();
  const recentFocusMap = (useSketchpad((s) => s.recentFocusItems) as Record<string, string[]>) || {};
  const recentFocusIds = recentFocusMap[appType] || [];
  const updateRecentFocusItems = useUpdateRecentFocusItems();

  const focusItems = focusContext?.focusItems || [];
  const triggerFocusItem = focusContext?.triggerFocusItem;
  const focusItemIndex = useMemo(() => {
    const map = new Map<string, FocusItem>();
    focusItems.forEach((item) => map.set(item.id, item));
    return map;
  }, [focusItems]);
  const recentFocusItems = useMemo(() => {
    return recentFocusIds.map((id) => focusItemIndex.get(id)).filter((item): item is FocusItem => !!item);
  }, [recentFocusIds, focusItemIndex]);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if ((e.ctrlKey || e.metaKey) && e.key === "f") {
        e.preventDefault();
        setOpen((prev) => !prev);
      }
    };
    window.addEventListener("keydown", handleKeyDown);
    return () => window.removeEventListener("keydown", handleKeyDown);
  }, []);

  const fuse = useMemo(
    () =>
      new Fuse(focusItems, {
        keys: [
          { name: "label", weight: 2 },
          { name: "description", weight: 1 },
          { name: "category", weight: 0.5 },
        ],
        threshold: 0.4,
        includeScore: true,
      }),
    [focusItems],
  );

  const focusResults = useMemo(() => {
    if (query.trim()) return fuse.search(query).slice(0, 20);

    const base = recentFocusItems.length > 0 ? recentFocusItems : focusItems.slice(0, 20);
    return base.map((item, idx) => ({ item, refIndex: idx }));
  }, [fuse, query, recentFocusItems, focusItems]);

  const handleSelect = useCallback(
    (item: FocusItem) => {
      const next = [item.id, ...recentFocusIds.filter((id) => id !== item.id)].slice(0, 20);
      const changed = next.length !== recentFocusIds.length || next.some((id, index) => id !== recentFocusIds[index]);
      if (changed) updateRecentFocusItems(appType, next);
      setOpen(false);
      setQuery("");
      if (triggerFocusItem) triggerFocusItem(item.id);
    },
    [appType, recentFocusIds, updateRecentFocusItems, triggerFocusItem],
  );

  const focusOtherLabel = useLabel("compose.sketchpad.navbar.focus.other");
  const groupedResults = useMemo(() => {
    const groups: Record<string, typeof focusResults> = {};
    focusResults.forEach((result) => {
      const category = result.item.category || focusOtherLabel || "";
      if (!groups[category]) groups[category] = [];
      groups[category].push(result);
    });
    return groups;
  }, [focusResults, focusOtherLabel]);

  if (!focusContext) return null;

  const focusTitle = useLabel("compose.sketchpad.navbar.focus.title");
  const focusDescription = useLabel("compose.sketchpad.navbar.focus.description");
  const focusPlaceholder = useLabel("compose.sketchpad.navbar.focus.placeholder");
  const focusNoResults = useLabel("compose.sketchpad.navbar.search.noResults");

  return (
    <>
      <Toggle id="compose.sketchpad.navbar.focus.open" i18nPressed="compose.sketchpad.navbar.focus.close" pressed={open} onPressedChange={setOpen} icon={<FocusIcon size={16} />} />
      <CommandDialog title={focusTitle} description={focusDescription} open={open} onOpenChange={setOpen}>
        <CommandInput id="compose.sketchpad.navbar.focus.input" placeholder={focusPlaceholder} value={query} onValueChange={setQuery} />
        <CommandList>
          <CommandEmpty>{focusNoResults}</CommandEmpty>
          {Object.entries(groupedResults).map(([category, items]) => (
            <CommandGroup key={category} heading={category}>
              {items.map((result, idx) => (
                <CommandItem key={`${result.item.id}-${idx}`} onSelect={() => handleSelect(result.item)}>
                  <div className="flex flex-col">
                    <span>{result.item.label}</span>
                    {result.item.description && <span className="text-xs text-muted-foreground">{result.item.description}</span>}
                  </div>
                </CommandItem>
              ))}
            </CommandGroup>
          ))}
        </CommandList>
      </CommandDialog>
    </>
  );
};

const PanelToggles: FC = ({}) => {
  const appType = useAppType();
  const visiblePanels = useAppPanelVisibility();
  const appCommands = useAppCommands();
  const leftTabs = useSidePanelTabs("left");
  const rightTabs = useSidePanelTabs("right");

  const hasLeftTabs = leftTabs.length > 0;
  const hasRightTabs = rightTabs.some((t) => !t.id.endsWith(".chat") && !t.id.endsWith(".settings"));

  const isLeftOpen = visiblePanels.leftSidePanel ?? false;
  const isRightOpen = visiblePanels.rightSidePanel ?? false;
  const isChatOpen = visiblePanels.chat ?? false;
  const isSettingsOpen = visiblePanels.settings ?? false;

  const handleLeftToggle = useCallback(
    (pressed: boolean) => {
      appCommands?.togglePanel?.("compose.sketchpad.navbar.panelToggle.leftSidePanel", "leftSidePanel");
    },
    [appCommands],
  );

  const handleRightToggle = useCallback(
    (pressed: boolean) => {
      if (pressed) {
        if (isChatOpen) appCommands?.togglePanel?.("compose.sketchpad.navbar.panelToggle.chat", "chat");
        if (isSettingsOpen) appCommands?.togglePanel?.("compose.sketchpad.navbar.panelToggle.settings", "settings");
      }
      appCommands?.togglePanel?.("compose.sketchpad.navbar.panelToggle.rightSidePanel", "rightSidePanel");
    },
    [appCommands, isChatOpen, isSettingsOpen],
  );

  const handleChatToggle = useCallback(
    (pressed: boolean) => {
      if (pressed) {
        if (isRightOpen) appCommands?.togglePanel?.("compose.sketchpad.navbar.panelToggle.rightSidePanel", "rightSidePanel");
        if (isSettingsOpen) appCommands?.togglePanel?.("compose.sketchpad.navbar.panelToggle.settings", "settings");
      }
      appCommands?.togglePanel?.("compose.sketchpad.navbar.panelToggle.chat", "chat");
    },
    [appCommands, isRightOpen, isSettingsOpen],
  );

  const handleSettingsToggle = useCallback(
    (pressed: boolean) => {
      if (pressed) {
        if (isRightOpen) appCommands?.togglePanel?.("compose.sketchpad.navbar.panelToggle.rightSidePanel", "rightSidePanel");
        if (isChatOpen) appCommands?.togglePanel?.("compose.sketchpad.navbar.panelToggle.chat", "chat");
      }
      appCommands?.togglePanel?.("compose.sketchpad.navbar.panelToggle.settings", "settings");
    },
    [appCommands, isRightOpen, isChatOpen],
  );

  const LeftIcon = leftTabs[0]?.icon;
  const RightIcon = rightTabs[0]?.icon;

  return (
    <div className="flex items-stretch gap-single">
      {hasLeftTabs && (
        <div className="flex items-stretch border border-element overflow-hidden h-medium">
          <Toggle kind="icon" id="compose.sketchpad.navbar.panelToggle.leftSidePanel" pressed={isLeftOpen} onPressedChange={handleLeftToggle} className="border-0" icon={LeftIcon ? <LeftIcon size={16} /> : <LayoutIcon size={16} />} />
        </div>
      )}
      <div className="flex items-stretch border border-element overflow-hidden h-medium divide-x divide-element">
        {hasRightTabs && (
          <Toggle kind="icon" id="compose.sketchpad.navbar.panelToggle.rightSidePanel" pressed={isRightOpen} onPressedChange={handleRightToggle} className="border-0" icon={RightIcon ? <RightIcon size={16} /> : <DocumentIcon size={16} />} />
        )}
        <Toggle kind="icon" id="compose.sketchpad.navbar.panelToggle.settings" pressed={isSettingsOpen} onPressedChange={handleSettingsToggle} className="border-0" icon={<SettingsIcon size={16} />} />
        <Toggle kind="icon" id="compose.sketchpad.navbar.panelToggle.chat" pressed={isChatOpen} onPressedChange={handleChatToggle} className="border-0" icon={<ChatIcon size={16} />} />
      </div>
    </div>
  );
};

