/**
 * Union of possible navigation state values.
 *
 *  * [👤compose📚js🗃️sketchpad💻sketchpad🔖machine🔖sketchpadmachine🔖sketchpadselectors🛠️navigationstate](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Machine/s/Sketchpad%20Machine/s/Sketchpad%20Selectors/d/i/NavigationState)
 **/
export type NavigationState = "home" | "kit" | "design" | "type" | "quality" | "docs";
/**
 * Selector deriving the current navigation state from the machine value.
 *
 *  * [👤compose📚js🗃️sketchpad💻sketchpad🔖machine🔖sketchpadmachine🔖sketchpadselectors🪨selectnavigationstate](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Machine/s/Sketchpad%20Machine/s/Sketchpad%20Selectors/d/i/selectNavigationState)
 **/
export const selectNavigationState = (state: { value: any }): NavigationState => {
  const value = state.value;
  if (typeof value === "object" && "navigation" in value) {
    const nav = value.navigation;
    if (typeof nav === "string") return nav as NavigationState;
    if (typeof nav === "object") {
      return Object.keys(nav)[0] as NavigationState;
    }
  }
  return "home";
};
