      setIsMobile: (origin: string, isMobile: boolean) => store.execute("compose.sketchpad.setIsMobile", origin, isMobile),
      setActiveInteraction: (origin: string, interactionId?: string) => store.execute("compose.sketchpad.setActiveInteraction", origin, interactionId),
      syncNavigation: (origin: string, path: string) => store.execute("compose.sketchpad.syncNavigation", origin, path),
      createKit: (origin: string, kit: Kit, local?: boolean, remote?: boolean) => store.execute("compose.sketchpad.createKit", origin, kit, local, remote),
      createKitApp: (origin: string, kitAppId: KitAppId) => store.execute("compose.sketchpad.createKitApp", origin, kitAppId),
      createDesignApp: (origin: string, designAppId: DesignAppId) => store.execute("compose.sketchpad.createDesignApp", origin, designAppId),
      navigateToKit: (kit: Guid, search?: string) => {
        const path = `/kits/${kit}${search ? (search.startsWith("?") ? search : `?${search}`) : ""}`;

        const globalNavigate = (window as any).__COMPOSE_NAVIGATE__;
        if (globalNavigate) {
          globalNavigate(path);
        } else {
          navigate(path);
        }
      },
      navigateToDesign: (kit: Guid, design: Guid) => {
        const path = `/kits/${kit}/designs/${design}`;

        const globalNavigate = (window as any).__COMPOSE_NAVIGATE__;
        if (globalNavigate) {
          globalNavigate(path);
        } else {
          navigate(path);
        }
      },
      navigateToType: (kit: Guid, type: Guid) => {
        const path = `/kits/${kit}/types/${type}`;

        const globalNavigate = (window as any).__COMPOSE_NAVIGATE__;
        if (globalNavigate) {
          globalNavigate(path);
        } else {
          navigate(path);
        }
      },
      navigateToQuality: (kit: Guid, quality: Guid) => {
        const path = `/kits/${kit}/qualities/${quality}`;

        const globalNavigate = (window as any).__COMPOSE_NAVIGATE__;
        if (globalNavigate) {
          globalNavigate(path);
        } else {
          navigate(path);
        }
      },
      navigateBack: (origin: string) => {
        store.execute("compose.sketchpad.navigateBack", origin);
        const state = store.snapshot();
        const targetPath = state.navigationHistory[state.navigationHistoryIndex];
        if (targetPath) {
          navigate(targetPath);
        }
      },
      navigateForward: (origin: string) => {
        store.execute("compose.sketchpad.navigateForward", origin);
        const state = store.snapshot();
        const targetPath = state.navigationHistory[state.navigationHistoryIndex];
        if (targetPath) {
          navigate(targetPath);
        }
      },
      setPanelSize: (origin: string, key: string, value: number) => {
        const state = store.snapshot();
        const currentSizes = state.panelSizes || {};
        const newSizes = { ...currentSizes, [key]: value };
        store.execute("compose.sketchpad.setState", origin, {
          panelSizes: newSizes,
        });
      },
      storeKitFileBlobs: async (kitGuid: Guid, kit: Kit) => {
        if (!store.hasKit(kitGuid)) return;
        const kitStore = store.kit(kitGuid);
        await kitStore.storeFileBlobs(kit);
      },
      getKitSnapshot: (kitGuid: Guid): Kit | null => {
        if (!store.hasKit(kitGuid)) return null;
        return store.kit(kitGuid).snapshot();
      },
    }),
    [store, navigate, reactNavigate],
  );
}

/**
 * Hook returning shallow kit data for all kits.
 *
 **/
export function useKits(): KitShallow[] {
  const store = useSketchpadStore();

  const kits = useSyncExternalStore(
    (onStoreChange) => {
      const unsubscribeCreated = store.onKitCreated(onStoreChange);
      const unsubscribeDeleted = store.onKitDeleted(onStoreChange);
      const unsubscribers = store.kitShallows().map((kitShallow) => {
        const kitStore = store.kit(kitShallow.guid);
        return kitStore.onChanged((cb: () => void) => {
          cb();
          onStoreChange();
          return () => {};
        });
      });
      return () => {
        unsubscribeCreated();
        unsubscribeDeleted();
        unsubscribers.forEach((unsub) => unsub());
      };
    },
    () => store.kitShallows(),
  );

}
