 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖appsregistry🛠️loadappconfigs](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Apps%20Registry/d/i/loadAppConfigs)
 * loadAppConfigs holds the data fields for a loadAppConfigs record.
 **/
async function loadAppConfigs() {
  if (appConfigsLoadPromise) return appConfigsLoadPromise;
  appConfigsLoadPromise = (async () => {
    const modules = await Promise.all([
      import("./Home"),
      import("./Kit"),
      import("./Type"),
      import("./Quality"),
      import("./Design"),
      import("./Docs"),
      import("./Feedback"),
    ]);
    for (const mod of modules) {
      if (!mod?.config) continue;
      appRegistry.register(mod.config as AppConfig);
