// Context provider for tracking the origin URL of the sketchpad instance.

/** OriginStore holds the data fields for a OriginStore record.
// [👤compose📚js🗃️sketchpad💻sketchpad🔖origin✂️originstore](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Origin/d/i/OriginStore)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖origin✂️originstore](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Origin/d/i/OriginStore)
 **/
type OriginStore = {
  subscribe: (callback: () => void) => () => void;
  getOrigin: () => string;
};

/** DEFAULT_ORIGIN holds the data fields for a DEFAULT_ORIGIN record.
// [👤compose📚js🗃️sketchpad💻sketchpad🔖origin🪨defaultorigin](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Origin/d/i/DEFAULT_ORIGIN)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖origin🪨defaultorigin](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Origin/d/i/DEFAULT_ORIGIN)
 **/
const DEFAULT_ORIGIN = "compose.sketchpad.unknown";

// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖origin🛠️createoriginstore](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Origin/d/i/createOriginStore)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖origin🪨createoriginstore](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Origin/d/i/createOriginStore)
 * createOriginStore holds the data fields for a createOriginStore record.
 **/
function createOriginStore(): OriginStore & { setOrigin: (origin: string) => void } {
  let origin = DEFAULT_ORIGIN;
  const listeners = new Set<() => void>();
  const subscribe = (callback: () => void) => {
    listeners.add(callback);
    return () => {
      listeners.delete(callback);
    };
  };
  const setOrigin = (next: string) => {
    if (origin === next) return;
    origin = next;
    listeners.forEach((cb) => cb());
  };
  return { subscribe, setOrigin, getOrigin: () => origin };
}

// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖origin🛠️resolveoriginfromtarget](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Origin/d/i/resolveOriginFromTarget)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖origin🛠️resolveoriginfromtarget](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Origin/d/i/resolveOriginFromTarget)
 **/
function resolveOriginFromTarget(target: EventTarget | null): string {
  if (!(target instanceof Element)) return DEFAULT_ORIGIN;
  const resolved = target.closest('[id^="compose.sketchpad."]')?.getAttribute("id") ?? "";
  if (!resolved) return DEFAULT_ORIGIN;
  if (!resolved.startsWith("compose.sketchpad.")) return DEFAULT_ORIGIN;
  return resolved;
}

// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖origin🪨origincontext](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Origin/d/i/OriginContext)
/**
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖origin🪨origincontext](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/Origin/d/i/OriginContext)
 * OriginContext holds the data fields for a OriginContext record.
 **/
const OriginContext = createContext<OriginStore | null>(null);

/**
 * React context provider tracking the UI origin of user interactions.
 *
 *  * [👤compose📚js🗃️sketchpad💻sketchpad🔖origin🪨originprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Origin/d/i/OriginProvider)
 **/
export const OriginProvider: FC<{ children: ReactNode }> = ({ children }) => {
  const storeRef = useRef<ReturnType<typeof createOriginStore> | null>(null);
  if (!storeRef.current) storeRef.current = createOriginStore();
  useEffect(() => {
    const store = storeRef.current;
    if (!store) return;
    const handler = (event: Event) => {
      store.setOrigin(resolveOriginFromTarget(event.target));
    };
    document.addEventListener("pointerdown", handler, true);
    document.addEventListener("keydown", handler, true);
    document.addEventListener("focusin", handler, true);
    return () => {
      document.removeEventListener("pointerdown", handler, true);
      document.removeEventListener("keydown", handler, true);
      document.removeEventListener("focusin", handler, true);
    };
  }, []);
  return <OriginContext.Provider value={storeRef.current}>{children}</OriginContext.Provider>;
};

/**
 * Hook returning a callback that resolves the current origin string.
 *
 *  * [👤compose📚js🗃️sketchpad💻sketchpad🔖origin🛠️useorigin](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Origin/d/i/useOrigin)
 **/
export function useOrigin(): () => string {
  const store = useContext(OriginContext);
  return useCallback(() => store?.getOrigin() ?? DEFAULT_ORIGIN, [store]);
}

/**
 * Hook returning the current origin string reactively.
 *
 *  * [👤compose📚js🗃️sketchpad💻sketchpad🔖origin🛠️useoriginvalue](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Origin/d/i/useOriginValue)
 **/
export function useOriginValue(): string {
  const store = useContext(OriginContext);
  return useSyncExternalStore(
    useCallback((callback: () => void) => (store ? store.subscribe(callback) : () => {}), [store]),
    useCallback(() => store?.getOrigin() ?? DEFAULT_ORIGIN, [store]),
  );
}

