                        text={typeof windowType.label === "string" ? windowType.label : typeId}
                      />
                    );
                  })}
                </ActionGroup>
              </div>
            </LevelProvider>,
            hoveredSplitter.element,
          )}
      </div>
    </CanvasContext.Provider>
  );
