    if (isTypeApp && type && typeof type === "object" && "parent" in type) {
      const typeObj = type as Type;
      if (typeObj.parent) {
        return `/kits/${kitGuid}/types/${typeObj.parent}`;
      }
      return `/kits/${kitGuid}?kind=types`;
    }

    if (isQualityApp) {
      return `/kits/${kitGuid}?kind=qualities`;
