    const subscribers = this.fieldSubscribers.get(key)!;
    subscribers.add(subscriberCallback);

    return () => {
      subscribers.delete(subscriberCallback);

      if (subscribers.size === 0) {
        const observer = this.fieldObservers.get(key);
        if (observer) {
