        if (observer) {
          observer();
          this.pathObservers.delete(pathKey);
        }
        this.pathSubscribers.delete(pathKey);
      }
    };
  }

  getPathSnapshot(path: YPath): any {
    return getValueAtPath(this.yMap, path);
  }

