// [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖plainappstorenoyjs🔖fileprovider🔖localfileproviderindexeddb](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Local%20File%20Provider%20(IndexedDB))
// Browser-local file storage provider backed by IndexedDB.

/**
 * Creates a file provider factory that persists files in IndexedDB.
 *
 *  * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖fileprovider🔖localfileproviderindexeddb🛠️createlocalfileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/File%20Provider/s/Local%20File%20Provider%20(IndexedDB)/d/i/createLocalFileProvider)
 *
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖store🔖fileprovider🔖localfileproviderindexeddb🪨createlocalfileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Store/s/File%20Provider/s/Local%20File%20Provider%20(IndexedDB)/d/i/createLocalFileProvider)
 *
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖fileprovider🔖localfileproviderindexeddb🪨createlocalfileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Local%20File%20Provider%20(IndexedDB)/d/i/createLocalFileProvider)
 *
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖store🔖plainappstorenoyjs🔖fileprovider🔖localfileproviderindexeddb🪨createlocalfileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Store/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Local%20File%20Provider%20(IndexedDB)/d/i/createLocalFileProvider)
 *
 * [👤compose📚js🗃️sketchpad💻sketchpad🔖utilities🔖plainappstorenoyjs🔖fileprovider🔖localfileproviderindexeddb🪨createlocalfileprovider](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/Sketchpad.tsx/s/Utilities/s/Plain%20App%20Store%20(No%20YJS)/s/File%20Provider/s/Local%20File%20Provider%20(IndexedDB)/d/i/createLocalFileProvider)
 **/
export function createLocalFileProvider(config?: LocalFileProviderConfig): FileProviderFactory {
  const dbName = config?.dbName || "compose-files";
  const storeName = config?.storeName || "files";

  const openDB = (): Promise<IDBDatabase> => {
    return new Promise((resolve, reject) => {
      const request = indexedDB.open(dbName, 1);

      request.onerror = () => reject(request.error);
      request.onsuccess = () => resolve(request.result);

      request.onupgradeneeded = (event) => {
        const db = (event.target as IDBOpenDBRequest).result;
        if (!db.objectStoreNames.contains(storeName)) {
          db.createObjectStore(storeName);
        }
      };
    });
  };

  return async (kitId: string): Promise<FileProvider> => {
    const getKey = (kitId: string, fileId: string, path: string): string => {
      return `${kitId}/${fileId}/${path}`;
    };

    return {
      upload: async (kitId, fileId, path, blob) => {
        const key = getKey(kitId, fileId, path);
        const db = await openDB();

        return new Promise<string>((resolve, reject) => {
          const transaction = db.transaction([storeName], "readwrite");
          const store = transaction.objectStore(storeName);
          const request = store.put(blob, key);

          request.onsuccess = () => {
            resolve(`local://${key}`);
          };
          request.onerror = () => reject(request.error);

          transaction.oncomplete = () => db.close();
        });
      },

      download: async (kitId, fileId, path) => {
        const key = getKey(kitId, fileId, path);
        const db = await openDB();

        return new Promise<Blob>((resolve, reject) => {
          const transaction = db.transaction([storeName], "readonly");
          const store = transaction.objectStore(storeName);
          const request = store.get(key);

          request.onsuccess = () => {
            const blob = request.result;
            if (!blob) {
              reject(new Error(`File not found in IndexedDB: ${key}`));
            } else {
              resolve(blob);
            }
          };
          request.onerror = () => reject(request.error);

          transaction.oncomplete = () => db.close();
        });
      },

      delete: async (kitId, fileId, path) => {
        const key = getKey(kitId, fileId, path);
        const db = await openDB();

        return new Promise<void>((resolve, reject) => {
          const transaction = db.transaction([storeName], "readwrite");
          const store = transaction.objectStore(storeName);
          const request = store.delete(key);

          request.onsuccess = () => {
            resolve();
          };
          request.onerror = () => reject(request.error);

          transaction.oncomplete = () => db.close();
        });
      },

      getUrl: (kitId, fileId, path) => {
        return `local://${kitId}/${fileId}/${path}`;
      },
    };
  };
}

