      diff: { qualities: { updated: [{ quality: { guid }, diff }] } },
    };
  },
  "compose.kit.deleteQuality": (context: KitCommandContext, guid: Guid): KitCommandResult => {
    return {
      diff: { qualities: { removed: [{ guid }] } },
    };
  },
  "compose.kit.createPort": (context: KitCommandContext, iface: Port): KitCommandResult => {
    return {
      diff: { ports: { added: [iface] } },
    };
  },
  "compose.kit.updatePort": (context: KitCommandContext, guid: Guid, diff: PortDiff): KitCommandResult => {
    return {
      diff: { ports: { updated: [{ port: { guid }, diff }] } },
    };
  },
  "compose.kit.deletePort": (context: KitCommandContext, guid: Guid): KitCommandResult => {
