    };
  },
  "compose.kit.updateTag": (context: KitCommandContext, guid: Guid, diff: TagDiff): KitCommandResult => {
    return {
      diff: { tags: { updated: [{ tag: { guid }, diff }] } },
    };
  },
  "compose.kit.deleteTag": (context: KitCommandContext, guid: Guid): KitCommandResult => {
    return {
      diff: { tags: { removed: [{ guid }] } },
    };
  },
  "compose.kit.createConcept": (context: KitCommandContext, concept: Concept): KitCommandResult => {
    return {
      diff: { concepts: { added: [concept] } },
    };
  },
  "compose.kit.updateConcept": (context: KitCommandContext, guid: Guid, diff: ConceptDiff): KitCommandResult => {
    return {
      diff: { concepts: { updated: [{ concept: { guid }, diff }] } },
    };
  },
  "compose.kit.deleteConcept": (context: KitCommandContext, guid: Guid): KitCommandResult => {
    return {
      diff: { concepts: { removed: [{ guid }] } },
    };
  },
  "compose.kit.addFile": (context: KitCommandContext, file: ComposeFile, blob?: Blob): KitCommandResult => {
    const files: File[] = blob ? [new File([blob], file.name)] : [];
    return {
      diff: { files: { added: [file] } },
      files,
    };
  },
  "compose.kit.addFiles": (context: KitCommandContext, foldersToAdd: Folder[], filesToAdd: { file: ComposeFile; blob?: Blob }[]): KitCommandResult => {
    const composeFiles: ComposeFile[] = [];
    const files: File[] = [];
    for (const { file, blob } of filesToAdd) {
      composeFiles.push(file);
      if (blob) files.push(new File([blob], file.name));
    }
    return {
      diff: { folders: { added: foldersToAdd }, files: { added: composeFiles } },
      files,
    };
  },
  "compose.kit.updateFile": (context: KitCommandContext, fileGuid: Url, fileDiff: FileDiff, blob?: Blob): KitCommandResult => {
    const existing = context.kit.files?.find((f) => f.guid === fileGuid);
    const fileName = fileDiff.name ?? existing?.name ?? "file";
    const files: File[] = blob ? [new File([blob], fileName)] : [];
    return {
      diff: { files: { updated: [{ file: { guid: fileGuid }, diff: fileDiff }] } },
      files,
    };
  },
  "compose.kit.removeFile": (context: KitCommandContext, fileGuid: Url): KitCommandResult => {
    return {
      diff: { files: { removed: [{ guid: fileGuid }] } },
    };
  },
  "compose.kit.createFolder": (context: KitCommandContext, folder: Folder): KitCommandResult => {
    return {
      diff: { folders: { added: [folder] } },
    };
  },
  "compose.kit.updateFolder": (context: KitCommandContext, guid: Guid, diff: FolderDiff): KitCommandResult => {
    return {
      diff: { folders: { updated: [{ folder: { guid }, diff }] } },
    };
  },
  "compose.kit.deleteFolder": (context: KitCommandContext, guid: Guid): KitCommandResult => {
    return {
      diff: { folders: { removed: [{ guid }] } },
    };
  },
  "compose.kit.moveToFolder": (context: KitCommandContext, artifactGuid: Guid, artifactKind: "type" | "design" | "quality" | "file" | "folder", folderGuid?: Guid): KitCommandResult => {
    switch (artifactKind) {
      case "type": {
        const type = context.kit.types?.find((t) => t.guid === artifactGuid);
        if (!type) throw new Error(`Type ${artifactGuid} not found`);
        const folderDiff = { folder: folderGuid };
      }
      case "design": {
        const design = context.kit.designs?.find((d) => d.guid === artifactGuid);
        if (design.parent) throw new Error("Only protodesigns (designs without parent) can be moved to folders");
        const folderDiff = { folder: folderGuid };
        return { diff: { designs: { updated: [{ design: { guid: artifactGuid }, diff: folderDiff }] } } };
      }
      case "quality": {
        const folderDiff = { folder: folderGuid };
        return { diff: { qualities: { updated: [{ quality: { guid: artifactGuid }, diff: folderDiff }] } } };
      }
      case "file": {
        const folderDiff = { folder: folderGuid ? { guid: folderGuid } : undefined };
        return { diff: { files: { updated: [{ file: { guid: artifactGuid }, diff: folderDiff }] } } };
      }
      case "folder": {
        return { diff: { folders: { updated: [{ folder: { guid: artifactGuid }, diff: parentDiff }] } } };
      }
      default:
        throw new Error(`Unknown artifact kind: ${artifactKind}`);
    }
  },
  "compose.kit.import": (context: KitCommandContext, url: string): KitCommandResult => {
    (async () => {
      try {
        if (url.endsWith(".json")) {
          const response = await fetch(url);
          const kit: Kit = await response.json();
          const filesToFetch: { path: string; url: string }[] = [];
          const extractFileUrls = (obj: any) => {
            if (typeof obj === "object" && obj !== null) {
              if (Array.isArray(obj)) {
                obj.forEach((item) => extractFileUrls(item));
              } else {
                Object.entries(obj).forEach(([key, value]) => {
                  if (key === "url" && typeof value === "string" && !value.startsWith("http")) {
                    filesToFetch.push({ path: value, url: new URL(value, url).href });
                  }
                  extractFileUrls(value);
                });
              }
            }
          };
          extractFileUrls(kit);
          const files: KitCommandResult["files"] = [];
          for (const file of filesToFetch) {
            try {
              const fileResponse = await fetch(file.url);
              const fileBlob = await fileResponse.blob();
              const fileName = file.path.split("/").pop() || file.path;
              files.push(new File([fileBlob], fileName));
            } catch (error) {}
          }
          return {
            diff: {
              name: kit.name,
              description: kit.description,
              version: kit.version,
              types: kit.types ? { added: kit.types } : undefined,
              designs: kit.designs ? { added: kit.designs } : undefined,
              files: kit.files ? { added: kit.files } : undefined,
            },
            files,
          };
        } else {
          const { kit } = await importKit(url);

          return {
            diff: {
              name: kit.name,
              description: kit.description,
              version: kit.version,
              types: kit.types && kit.types.length > 0 ? { added: kit.types } : undefined,
              designs: kit.designs && kit.designs.length > 0 ? { added: kit.designs } : undefined,
              files: kit.files && kit.files.length > 0 ? { added: kit.files } : undefined,
            },
          };
        }
      } catch (error) {
        throw error;
      }
    })();
    return { diff: {} };
  },
  "compose.kit.export": (context: KitCommandContext): KitCommandResult => {
    (async () => {
      try {
        const kit = context.kit;

        for (const [path, url] of context.fileUrls.entries()) {
          try {
            const response = await fetch(url);
            if (response.ok) {
              const blob = await response.blob();
              files.set(path, blob);
            }
          } catch (error) {
            // File not accessible, skip
          }
        }

        const zipBlob = await exportKit(kit, files);
        const url = URL.createObjectURL(zipBlob);
        const a = document.createElement("a");
        a.href = url;
        a.download = `${kit.name}-${kit.version || "latest"}.compose.zip`;
        document.body.appendChild(a);
        a.click();
        document.body.removeChild(a);
        URL.revokeObjectURL(url);
      } catch (error) {
        throw error;
      }
    })();
    return { diff: {} };
  },
  "compose.kit.addPiece": (context: KitCommandContext, guid: Guid, piece: Piece): KitCommandResult => {
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: {
                pieces: {
                  added: [
                    piece.plane || (findDesignInKit(context.kit, guid)?.connections ?? []).some((connection) => connection.connected.piece.guid === piece.guid || connection.connecting.piece.guid === piece.guid)
                      ? piece
                      : {
                          ...piece,
                          plane: {
                            origin: { x: 0, y: 0, z: 0 },
                            xAxis: { x: 1, y: 0, z: 0 },
                            yAxis: { x: 0, y: 1, z: 0 },
                          },
                        },
                  ],
                },
              },
            },
          ],
        },
      },
    };
  },
  "compose.kit.addPieces": (context: KitCommandContext, guid: Guid, pieces: Piece[]): KitCommandResult => {
    const design = findDesignInKit(context.kit, guid);
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: {
                pieces: {
                  added: pieces.map((candidate) =>
                    candidate.plane || (design?.connections ?? []).some((connection) => connection.connected.piece.guid === candidate.guid || connection.connecting.piece.guid === candidate.guid)
                      ? candidate
                      : {
                          ...candidate,
                          plane: {
                            origin: { x: 0, y: 0, z: 0 },
                            xAxis: { x: 1, y: 0, z: 0 },
                            yAxis: { x: 0, y: 1, z: 0 },
                          },
                        },
                  ),
                },
              },
            },
          ],
        },
      },
    };
  },
  "compose.kit.removePiece": (context: KitCommandContext, guid: Guid, piece: Guid): KitCommandResult => {
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: { pieces: { removed: [{ guid: piece }] } },
            },
          ],
        },
      },
    };
  },
  "compose.kit.removePieces": (context: KitCommandContext, guid: Guid, pieces: Guid[]): KitCommandResult => {
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: { pieces: { removed: pieces.map((p) => ({ guid: p })) } },
            },
          ],
        },
      },
    };
  },
  "compose.kit.addConnection": (context: KitCommandContext, guid: Guid, connection: Connection): KitCommandResult => {
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: { connections: { added: [connection] } },
            },
          ],
        },
      },
    };
  },
  "compose.kit.addConnections": (context: KitCommandContext, guid: Guid, connections: Connection[]): KitCommandResult => {
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: { connections: { added: connections } },
            },
          ],
        },
      },
    };
  },
  "compose.kit.removeConnection": (context: KitCommandContext, guid: Guid, connectionGuid: Guid): KitCommandResult => {
    const design = findDesignInKit(context.kit, guid);
    const connection = design?.connections?.find((c) => c.guid === connectionGuid);
    if (!connection) return { diff: {} };
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: { connections: { removed: [{ guid: connection.guid }] } },
            },
          ],
        },
      },
    };
  },
  "compose.kit.removeConnections": (context: KitCommandContext, guid: Guid, connectionGuids: Guid[]): KitCommandResult => {
    return {
      diff: {
        designs: {
          updated: [
            {
              design: { guid },
              diff: { connections: { removed: connectionGuids.map((connGuid) => ({ guid: connGuid })) } },
            },
          ],
        },
      },
    };
  },
};

