    if (event.keysChanged.has(mapKey)) {
      const prevInArray = wasInArray;

      if (arrayDisposer) {
        arrayDisposer();
        arrayDisposer = null;
      }
      if (nestedMapDisposer) {
        nestedMapDisposer();
        nestedMapDisposer = null;
      }

      setupNestedMapObserver();
      setupArrayObserver();
      wasInArray = checkMembership();

      if (wasInArray !== prevInArray) {
        notifySubscriber();
      }
    }
  };

  wasInArray = checkMembership();
  setupNestedMapObserver();
  setupArrayObserver();
