      return () => subscription.unsubscribe();
    }
    return createObserver(this.ySketchpad, subscribe);
  };

  onChangedDeep = (subscribe: Subscribe): Unsubscribe => {
    if (this.actor) {
      const subscription = this.actor.subscribe(() => {
