}

/**
 * Props interface for the Footer component.
 *
 * [👤compose📚js🗃️sketchpad💻elements🔖footer🛠️footer](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/elements.tsx/s/Footer/d/i/Footer)
 **/
export interface FooterProps {
  items?: FooterItem[];
  className?: string;
  isVisible?: boolean;
}

// [👤compose📚js🗃️sketchpad💻elements🔖footer🪨footer](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/elements.tsx/s/Footer/d/i/Footer)
/**
 * [👤compose📚js🗃️sketchpad💻elements🔖footer🪨footer](composerepo://p/u/compose/b/l/js/fd/org/sketchpad/f/elements.tsx/s/Footer/d/i/Footer)
 * Footer holds the data fields for a Footer record.
 **/
const Footer: React.FC<FooterProps> = ({ items = [], className = "", isVisible = true }) => {
  const level = useLevel();
  const sortedItems = [...items].sort((a, b) => (a.order || 0) - (b.order || 0));
  const bgClass = getLevelBgClass(level);
  return (
    <footer id="compose.sketchpad.footer" data-slot="footer" className={cn("border-t flex items-center h-medium transition-transform duration-200", bgClass, isVisible ? "translate-y-0" : "translate-y-full", className)}>
      <div className="flex items-center h-full px-single min-w-0">
        <ActionGroup className="border">
          {sortedItems.map((item) => (
            <ActionGroupItem key={item.id} as={item.onClick ? "button" : "div"} id={item.id} text={item.text} onClick={item.onClick} disabled={item.disabled} className={cn(item.content && !item.text && "aspect-auto", item.className)}>
              {item.content ?? item.icon}
            </ActionGroupItem>
          ))}
        </ActionGroup>
      </div>
    </footer>
  );
};

export { Footer };

